  svg.append("text")
    .attr("x", width / 2).attr("y", height / 2)
    .attr("text-anchor", "middle")
    .attr("font-family", fontFamily).attr("font-size", 14).attr("fill", axisCol)
    .text("No data available for hexbin_plot()");
  return;
}

// ---------------------------------------------------------------------------
// Layout
// ---------------------------------------------------------------------------
