  gridG.selectAll("line.gx")
    .data(xScale.ticks(xTickCount))
    .join("line").attr("class", "gx")
    .attr("x1", d => xScale(d)).attr("x2", d => xScale(d))
    .attr("y1", 0).attr("y2", chartH)
    .attr("stroke", gridCol).attr("stroke-width", 1);
