  legendG.selectAll("g.item").style("opacity", d => hidden.has(d.s.name) ? 0.4 : (name === null || d.s.name === name ? 1 : 0.45));
  gEnd.selectAll("g.endlab").style("opacity", d => name === null || d.s.name === name ? 1 : 0.3);
